#include "WiFiS3.h"
// Join Wi-Fi through the ESP32-S3 and print the IP address and the signal
const char SSID[] = "{{p:ssid}}";
const char PASS[] = "iynk-demo";    // in a real sketch, keep passwords in arduino_secrets.h

void setup() {
  Serial.begin(115200);
  Serial.print("Connecting to ");
  Serial.println(SSID);
  WiFi.begin(SSID, PASS);
  unsigned long start = millis();
  while (WiFi.status() != WL_CONNECTED && millis() - start < 10000) {
    delay(500);
    Serial.print(".");
  }
  Serial.println();
  if (WiFi.status() == WL_CONNECTED) {
    Serial.print("Connected, IP ");
    Serial.println(WiFi.localIP());
    Serial.print("Signal ");
    Serial.print(WiFi.RSSI());
    Serial.println(" dBm");
  } else {
    Serial.println("Not connected: check the name and password");
  }
}

void loop() {
}

